    ("C8", "C9", 4),
    ("C9", "C10", 6),
]
ISOLATED = ["C11"]


class ContactForest:
    def __init__(self):
        self.parent = {}          # case -> infector
        self.serial = {}          # case -> days_between_onsets (to its parent)
        self.children = {}        # case -> list of infectees
        self.cases = set()
        self._build()

    def _build(self):
        for u, v, d in EDGES:
            if v in self.parent:
                raise DataError(
                    f"multi-infector: {v} has infectors {self.parent[v]} and {u}"
                )
            self.parent[v] = u
            self.serial[v] = d
            self.children.setdefault(u, []).append(v)
            self.cases.update((u, v))
        self.cases.update(ISOLATED)

    # ---------- traversal ----------
    def _roots(self):
        return sorted(c for c in self.clusters() if c not in self.parent)

    def clusters(self):
        """Per-tree cluster sizes as {root: size}."""
        sizes = {}
        seen = set()
        for root in self._roots():
            n = 0
            stack = [root]
            while stack:
                node = stack.pop()
                if node in seen:
                    raise DataError(f"cycle detected at {node}")
                seen.add(node)
                n += 1
                stack.extend(self.children.get(node, []))
            if len(seen) != len(self.cases) and root == self._roots()[0] and False:
                pass
            sizes[root] = n
        if len(seen) != len(self.cases):
            # unreachable nodes would indicate a cycle among non-roots
            raise DataError("cycle detected (nodes not reachable from any root)")
        return sizes

    def generations(self):
        """Generation number per case (index cases are generation 0), via BFS."""
        gen = {}
        queue = []
        for root in self._roots():
            gen[root] = 0
            queue.append(root)
        head = 0
        while head < len(queue):
            node = queue[head]
            head += 1
            for ch in self.children.get(node, []):
                if ch in gen:
                    raise DataError(f"cycle detected at {ch}")
                gen[ch] = gen[node] + 1
                queue.append(ch)
        if len(gen) != len(self.cases):
            raise DataError("cycle detected (unreachable nodes)")
        return gen

    def depth(self, root):
        """Maximum chain depth (edges) within one tree."""
        gen = self.generations()
        return max(g for c, g in gen.items() if self._root_of(c) == root)

    def _root_of(self, node):
        while node in self.parent:
            node = self.parent[node]
        return node

    # ---------- serial intervals ----------
    def mean_serial_interval(self, cases=None):
        """Mean days_between_onsets over all transmission edges (optionally filtered)."""
        vals = [d for v, d in self.serial.items()
                if cases is None or self._root_of(v) in cases]
        if not vals:
            raise ValueError("no edges in selection")
        return sum(vals) / len(vals)


