    f = ContactForest()
    clusters = f.clusters()
    gens = f.generations()
    return {
        "clusters": clusters,
        "generations": gens,
        "mean_serial_interval_overall": f.mean_serial_interval(),
        "mean_serial_interval_per_cluster": {
            r: f.mean_serial_interval(cases={r}) for r in clusters
        },
        "max_depth_per_cluster": {r: f.depth(r) for r in clusters},
    }


if __name__ == "__main__":
    import pprint
    pprint.pprint(analyze())
